  const rented=data.equipment.reduce((sum,e)=>sum+(e.active_rentals||0),0),available=data.equipment.reduce((sum,e)=>sum+(e.available_qty??e.stock_qty??1),0),total=data.equipment.reduce((sum,e)=>sum+(e.stock_qty??1),0);
