function localDate(value){
  if(!value)return null;
  const text=String(value).trim(),date=new Date(/^\d{4}-\d{2}-\d{2}$/.test(text)?`${text}T00:00:00`:text.replace(' ','T'));
  return Number.isNaN(date.getTime())?null:date;
}
function companyRange(){
  const now=new Date(),start=new Date(now);
  start.setHours(0,0,0,0);
  if(companyPeriod==='month')start.setDate(1);
  else if(companyPeriod==='year'){start.setMonth(0,1);}
  else return {start:null,end:now};
  return {start,end:now};
}
function companyIncludes(value){const date=localDate(value),range=companyRange();return !!date&&(!range.start||date>=range.start)&&date<=range.end;}
function companyBuckets(){
  const now=new Date();
  if(companyPeriod==='month')return Array.from({length:5},(_,index)=>({label:`Sem. ${index+1}`,match:date=>date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()&&Math.min(4,Math.floor((date.getDate()-1)/7))===index}));
  if(companyPeriod==='year')return ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'].map((label,index)=>({label,match:date=>date.getFullYear()===now.getFullYear()&&date.getMonth()===index}));
  const dates=[...(data.cash_movements||[]).map(item=>localDate(item.created_at)),...(data.payables||[]).map(item=>localDate(item.paid_at))].filter(Boolean);
  const first=dates.length?Math.min(...dates.map(date=>date.getFullYear())):now.getFullYear();
  return Array.from({length:now.getFullYear()-first+1},(_,index)=>{const year=first+index;return {label:String(year),match:date=>date.getFullYear()===year};});
}
function companyNavigation(){return `<div class="company-subnav" role="tablist" aria-label="Minha Empresa"><button type="button" role="tab" aria-selected="${companySection==='overview'}" class="${companySection==='overview'?'active':''}" data-action="company-section" data-section="overview">Visão geral</button><button type="button" role="tab" aria-selected="${companySection==='profile'}" class="${companySection==='profile'?'active':''}" data-action="company-section" data-section="profile">Dados da empresa</button></div>`;}
