  $('#stats').innerHTML=`<div class="stat company-stat received"><p>Valores recebidos</p><strong>${money(received)}</strong><small>${inflows.length} recebimento(s) no período</small></div><div class="stat company-stat paid"><p>Contas pagas</p><strong>${money(paidTotal)}</strong><small>${paid.length} pagamento(s) no período</small></div><div class="stat company-stat balance"><p>Resultado financeiro</p><strong>${money(result)}</strong><small>Recebimentos menos contas pagas</small></div><div class="stat company-stat rentals"><p>Locações realizadas</p><strong>${rentals.length}</strong><small>${rentals.reduce((sum,item)=>sum+item.total_cents,0)?money(rentals.reduce((sum,item)=>sum+item.total_cents,0)):'Nenhum valor'} contratado</small></div>`;
  const equipmentRanking=Object.values(rentals.reduce((map,item)=>{const key=item.equipment_id||item.equipment_name;(map[key]??={name:item.equipment_name||'Equipamento',count:0,total:0});map[key].count++;map[key].total+=item.total_cents||0;return map;},{})).sort((a,b)=>b.count-a.count||b.total-a.total).slice(0,6);
  const methodKeys=['cash','pix','debit','credit','term'],methodTotals=methodKeys.map(method=>({method,label:paymentLabels[method],value:inflows.filter(item=>(item.payment_method||'term')===method).reduce((sum,item)=>sum+item.amount_cents,0)})),methodMax=Math.max(1,...methodTotals.map(item=>item.value)),rankingMax=Math.max(1,...equipmentRanking.map(item=>item.count));
