  <div class="company-open-grid"><article><span>A receber</span><strong>${money(receivableTotal)}</strong><small>${receivables.length} conta(s) em aberto</small></article><article><span>A pagar</span><strong>${money(payableTotal)}</strong><small>${payables.length} conta(s) em aberto</small></article><article class="attention"><span>Recebimentos vencidos</span><strong>${money(lateReceivables.reduce((sum,item)=>sum+item.amount_cents,0))}</strong><small>${lateReceivables.length} conta(s) exigem atenção</small></article><article class="attention"><span>Pagamentos vencidos</span><strong>${money(latePayables.reduce((sum,item)=>sum+item.amount_cents,0))}</strong><small>${latePayables.length} conta(s) exigem atenção</small></article></div>
