function renderCash(){
  $('#title').textContent='Caixa';$('#subtitle').textContent=cashPeriod==='today'?'Movimentações e recebimentos do dia.':'Consulta de movimentações por período.';
  $('#new-record').hidden=true;$('#list-title').textContent='Movimentações do caixa';$('#search').closest('.search').hidden=true;$('#cash-query').hidden=false;
  document.querySelectorAll('[data-view]').forEach(button=>{const active=button.dataset.view===view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  let start=null;
  if(cashPeriod==='today'){start=new Date();start.setHours(0,0,0,0);}
  else if(cashPeriod==='7'||cashPeriod==='30'){start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-Number(cashPeriod)+1);}
  else if(cashPeriod==='month'){start=new Date();start.setHours(0,0,0,0);start.setDate(1);}
  const entries=(data.cash_movements||[]).filter(m=>m.direction==='inflow'&&(!start||new Date(m.created_at)>=start)&&(cashMethod==='all'||m.payment_method===cashMethod));
  const byMethod=Object.fromEntries(['cash','pix','debit','credit'].map(method=>[method,entries.filter(m=>m.payment_method===method).reduce((sum,m)=>sum+m.amount_cents,0)]));
  const total=entries.reduce((sum,m)=>sum+m.amount_cents,0);
  $('#stats').classList.add('cash-stats');
  $('#stats').innerHTML=`<div class="stat cash-in"><p>Entradas de ${cashPeriod==='today'?'hoje':'consulta'}</p><strong>${money(total)}</strong><small>${entries.length} ${entries.length===1?'locação recebida':'locações recebidas'}</small></div><div class="stat cash-out"><p>Saídas</p><strong>${money(0)}</strong><small>Nenhuma saída registrada</small></div><div class="stat cash-balance"><p>Saldo ${cashPeriod==='today'?'de hoje':'da consulta'}</p><strong>${money(total)}</strong><small>Entradas menos saídas registradas</small></div><div class="stat cash-money"><p>Recebido em dinheiro</p><strong>${money(byMethod.cash)}</strong><small>Somente locações pagas em dinheiro</small></div>`;
  $('#cash-controls').hidden=!cashQueryOpen;
  $('#toggle-cash-query').textContent=cashQueryOpen?'Fechar consulta':'⌕ Consultar outro período';
  $('#cash-period').value=cashPeriod;$('#cash-method').value=cashMethod;
  $('#cash-summary').innerHTML=Object.entries(paymentLabels).map(([method,label])=>`<div class="cash-payment ${method}"><span>${esc(label)}</span><strong>${money(byMethod[method])}</strong></div>`).join('');
  const term=normalize($('#cash-search').value);
  const rows=entries.filter(m=>normalize(m.description).includes(term));
  if(!rows.length){$('#records').innerHTML=`<div class="empty"><div class="empty-icon" aria-hidden="true">▣</div><h3>${term?'Nenhuma movimentação encontrada':'Nenhuma entrada neste período'}</h3><p>${term?'Tente outra busca.':'As locações salvas com forma de recebimento aparecem aqui automaticamente.'}</p></div>`;return;}
  $('#records').innerHTML=`<div class="table-wrap"><table class="cash-table"><thead><tr><th>Data</th><th>Movimento</th><th>Descrição</th><th>Forma de pagamento</th><th>Valor</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(m.created_at))}</td><td><span class="cash-tag">Entrada</span></td><td><strong>${esc(m.description)}</strong><small>${esc(m.category)}</small></td><td>${esc(paymentLabels[m.payment_method]||'—')}</td><td class="cash-amount">+ ${money(m.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`;
}
function field(label,key,value='',options={}){return `<label class="field ${options.wide?'wide':''}">${label}${options.required?' *':''}<input data-field="${key}" value="${esc(value)}" ${options.required?'required':''} maxlength="${options.max||300}" ${options.inputmode?`inputmode="${options.inputmode}"`:''} type="${options.type||'text'}" ${options.min!=null?`min="${options.min}"`:''} ${options.max!=null&&options.type==='number'?`max="${options.max}"`:''} ${options.placeholder?`placeholder="${esc(options.placeholder)}"`:''}></label>`;}
function openEditor(id,copy=false){
  if(view==='dashboard'){view='equipment';$('#search').value='';render();}
  draft=id?structuredClone(data[view].find(r=>r.id===id)):(view==='clients'||view==='suppliers')?{name:'',document:'',phone:'',email:'',notes:'',addresses:[]}:{name:'',code:'',category:'',daily_cents:null,asset_value_cents:null,stock_qty:1,notes:'',promotions:[]};
  if(!draft)return;
  copyingEquipment=copy&&view==='equipment';
  if(copyingEquipment){delete draft.id;delete draft.created_at;delete draft.updated_at;delete draft.active_rentals;delete draft.available_qty;draft.name=`${draft.name} - Cópia`;draft.code='';draft.status='available';draft.promotions=(draft.promotions||[]).map(p=>{const item={...p};delete item.id;delete item.equipment_id;return item;});}
  if(view==='equipment'){draft.status??='available';draft.icon??='tool';draft.stock_qty??=1;draft.daily=decimal(draft.daily_cents);draft.asset_value=decimal(draft.asset_value_cents);draft.promotions=draft.promotions.map(p=>({...p,total:decimal(p.total_cents)}));}
  dirty=false;tab='general';$('#editor-title').textContent=copyingEquipment?'Copiar equipamento':(id?'Editar ':'Novo ')+(view==='clients'?'cliente':view==='suppliers'?'fornecedor':'equipamento');$('#save').textContent=copyingEquipment?'Salvar cópia':'Salvar cadastro';$('#form-error').hidden=true;renderEditor();$('#editor').showModal();
}
